// The real extractor's output (generated by verification/make_fixtures.py) through the real ingest().
import { expect, test } from 'claude-code/testing'

import { emptyAgg, ingest, makeResolver, normPath, stats } from '../hooks/agg'
import { REAL } from './fixtures/real-history'
import { SYN } from './fixtures/extract-fixtures'
import type { History } from './fixtures/synthetic-history'
import { makeHistory } from './fixtures/synthetic-history'

const totals = (a: ReturnType<typeof emptyAgg>) => {
  const st = stats(a, makeResolver(a, []), '0000-01-01', '9999-12-31')
  const sess = Object.values(a.sess)
  return {
    responses: sess.reduce((n, s) => n + s.resp, 0),
    sideResponses: sess.reduce((n, s) => n + s.side, 0),
    activity: st.all.tokens,
    cacheReads: st.all.cr,
    prompts: st.all.prompts,
    compactions: sess.reduce((n, s) => n + s.comp, 0),
  }
}

test('dedupe fixtures: content blocks, placeholder, synthetic, fork, resume, /clear, rewind, orphan, subagent, refresh boundary', async () => {
  const a = emptyAgg()
  const r1 = ingest(a, SYN.phase1, SYN.files.map(f => ({ ...f })))
  expect(r1.next.length).toBe(0)
  // Phase 2: the rest of msg_9's content blocks arrive after the offset; msg_9 must not count twice.
  ingest(a, SYN.phase2, SYN.tasks2.map(f => ({ ...f })))
  expect(totals(a)).toEqual(SYN.expect)
  // The fork/resume copies stayed with S1; /clear's new session S4 counts on its own.
  expect(a.sess.S2.resp).toBe(1)
  expect(a.sess.S3.resp).toBe(1)
  expect(a.sess.S4.resp).toBe(1)
  // Both branches of the rewind in S1 ran, so both count: msg_1..msg_4.
  expect(a.sess.S1.resp).toBe(4)
  expect(a.sess.GONE.resp).toBe(1) // orphan copy present in two files, counted once
})

// ---------------------------------------------------------------- whole-history checks
//
// The same two checks run on two histories:
//   - a synthetic one (tests/fixtures/synthetic-history.ts): always runs;
//   - the owner's real one (tests/fixtures/real-history.ts): private, not distributed. When it
//     is absent its tests are NOT registered, so they are never counted as passes; a
//     "(skip)" line says so instead.

const skipped: string[] = []
/** Registers a test only when its private fixture is present; otherwise reports it as skipped. */
const testIf = (present: unknown, name: string, body: () => unknown) => {
  if (present) { test(name, async () => { await body() }); return }
  skipped.push(name)
  console.log(`(skip) ${name} [private fixture not present]`)
}

/** Extractor output through ingest equals a count made separately. */
const checkTotals = (h: History) => {
  const a = emptyAgg()
  const res = ingest(a, h.out, h.tasks.map((t: any) => ({ ...t })))
  expect(res.next.length).toBe(0)
  const t = totals(a)
  expect(t.responses + t.sideResponses).toBe(h.expect.responses_all)
  expect(t.activity).toBe(h.expect.activity)
  expect(t.cacheReads).toBe(h.expect.cacheReads)
  expect(t.prompts).toBe(h.expect.prompts)
  return a
}

/** Project detection: generic invariants that hold for any history. Returns what it found. */
const checkProjects = (h: History) => {
  const a = emptyAgg()
  ingest(a, h.out, h.tasks.map((t: any) => ({ ...t })))
  const resolve = makeResolver(a, [])
  const roots = [...new Set(Object.values(a.sess).map(s => s.root).filter(Boolean) as string[])]
  const cwds = [...new Set(Object.keys(a.rows).map(k => k.split('\t')[2]))].sort()
  const map: Record<string, string> = {}
  for (const c of cwds) {
    const p = resolve(c)
    map[c] = `${p.name} [${p.source}]`
    // Invariant: a project is the cwd itself, a launch root, or one folder below a launch root.
    const ok = roots.some(r => normPath(p.key) === normPath(r).toLowerCase()
      || (normPath(p.key).startsWith(normPath(r).toLowerCase() + '\\') && !normPath(p.key).slice(normPath(r).length + 1).includes('\\')))
      || p.source !== 'root'
    expect(ok).toBe(true)
    // Invariant: everything under a project folder (other than a launch root itself) resolves to that same project.
    if (!roots.some(r => normPath(r).toLowerCase() === p.key)) expect(resolve(p.key + '\\some\\deeper\\folder').key).toBe(p.key)
  }
  const st = stats(a, resolve, '0000-01-01', '9999-12-31')
  return { a, roots, map, st, resolve }
}

test('synthetic history: ingest equals an independent count; duplicate copies and a corrupt row never count', async () => {
  const h = makeHistory()
  const a = checkTotals(h)
  expect(a.flagged).toBe(h.expect.flagged)
  expect(h.expect.flagged > 0).toBe(true)
  expect(Object.keys(a.sess).length).toBe(h.expect.sessions)
  expect(Object.values(a.sess).reduce((n, s) => n + s.comp, 0)).toBe(h.expect.compactions)
  // The history is big enough to mean something, and the same on every run.
  expect(h.expect.responses_all > 300).toBe(true)
  expect(makeHistory().out).toBe(h.out)
  // Reading the same answer again adds nothing (every row is already known for its file).
  const again = ingest(a, h.out, h.tasks.map(t => ({ ...t })))
  expect(again.rows).toBe(0)
  expect(totals(a).activity).toBe(h.expect.activity)
})

test('synthetic history: project detection (launch roots, sub-folders, one folder below a shared root)', async () => {
  const { map, st, resolve } = checkProjects(makeHistory())
  // Work inside a project's sub-folders stays with the project.
  expect(resolve('D:\\Work\\Atlas\\web\\src').key).toBe(resolve('D:\\Work\\Atlas').key)
  expect(resolve('D:\\Work\\Borealis\\api').key).toBe(resolve('D:\\Work\\Borealis').key)
  // A session launched from the shared parent and moved into a folder: that folder is the project.
  expect(resolve('D:\\Work\\Cygnus\\docs').key).toBe(resolve('D:\\Work\\Cygnus').key)
  expect(resolve('D:\\Work\\Cygnus').key).not.toBe(resolve('D:\\Work\\Atlas').key)
  const names = [...st.byProject.keys()].map(k => String(st.names.get(k)).toLowerCase())
  for (const n of ['atlas', 'borealis', 'cygnus', 'sandbox']) expect(names).toContain(n)
  expect(Object.keys(map).length >= 8).toBe(true)
})

testIf(REAL, 'real history: the extractor + ingest equal an independent count (global message.id dedupe)', () => { checkTotals(REAL) })

testIf(REAL, 'real history: project detection (reported, and generic invariants hold)', () => {
  const { roots, map, st } = checkProjects(REAL)
  const projects = [...st.byProject.entries()].map(([k, s]) => `${st.names.get(k)} | ${k} | activity ${s.tokens} | sessions ${s.sessions.size}`)
  console.log('LAUNCH ROOTS: ' + JSON.stringify(roots))
  console.log('CWD -> PROJECT: ' + JSON.stringify(map, null, 1))
  console.log('PROJECTS: ' + JSON.stringify(projects, null, 1))
})

if (skipped.length) console.log(`(skip) ${skipped.length} test(s) skipped in this file; they are not counted as passed.`)
